import {apiRequest} from './api-client.js';
/** Storage controls fail closed. Uploads use a scoped gateway, never reusable S3 presigned requests. */
export function mountR2Studio(root,{selectedTitle,release,toast,onPublished,onCleanup}){
 const section=document.createElement('section');section.className='state-panel r2-controls';section.innerHTML='<h3>3. Upload movie or episode · Private R2</h3><p class="r2-intro">Encode the original locally with tools/encode_hls.py, then choose its HLS output folder. Originals remain on your computer. All uploaded renditions share an 8 GB reservation cap.</p><button class="button button-secondary" id="r2Usage">Check usage & renewal dates</button><details><summary>Storage limits and renewal details</summary><pre id="r2Limits" class="muted"></pre></details><div class="r2-progress-card" aria-live="polite"><strong id="r2ProgressLabel">Step 1: Select an episode or movie draft above.</strong><progress id="r2Progress" max="100" value="0" style="width:100%;height:24px"></progress><p id="r2Transfer">Then select its encoded HLS folder and upload.</p></div><label>Encoded HLS folder<input id="r2Files" type="file" webkitdirectory multiple></label><label hidden><input id="r2Resume" type="checkbox"> Resume an existing reservation</label><button class="button button-primary" id="r2Upload">Upload HLS bundle</button><label><input id="r2Rights" type="checkbox"> I reviewed distribution rights.</label><label><input id="r2Captions" type="checkbox"> I reviewed captions and accessibility.</label><button class="button button-secondary" id="r2Publish" disabled>Publish R2 video</button><p id="r2Status" role="status">No upload in progress.</p>';root.append(section);
 const $=id=>section.querySelector('#'+id);let reservation=null,title=null,closed=false,controller=null,transferred=false;onCleanup?.(()=>{closed=true;controller?.abort();});
 root.addEventListener('studio:selection',()=>{$('r2Rights').checked=$('r2Captions').checked=false;try{$('r2Publish').disabled=!transferred||selectedTitle()!==title;}catch{$('r2Publish').disabled=true;}});
 $('r2Files').onchange=()=>{transferred=false;$('r2Publish').disabled=true;const files=[...$('r2Files').files];$('r2Transfer').textContent=`${files.length} files selected · ${(files.reduce((n,f)=>n+f.size,0)/1e6).toFixed(1)} MB. Click Upload HLS bundle to begin.`;};
 $('r2Usage').onclick=async()=>{try{const usage=await apiRequest('/api/admin/storage/limits');$('r2Limits').textContent=JSON.stringify(usage,null,2);}catch(e){$('r2Limits').textContent=e.message;}};
 $('r2Upload').onclick=async()=>{const button=$('r2Upload');button.disabled=true;root.dispatchEvent(new CustomEvent('studio:upload-state',{detail:{state:'uploading'}}));try{
  transferred=false;$('r2Publish').disabled=true;$('r2ProgressLabel').textContent='Preparing upload…';$('r2Status').textContent='Validating draft and HLS files…';title=selectedTitle();const files=[...$('r2Files').files].filter(f=>/^[A-Za-z0-9_-]+\.(m3u8|ts|m4s|mp4)$/.test(f.name));
  if(!files.some(f=>f.name==='master.m3u8')||new Set(files.map(f=>f.name)).size!==files.length)throw new Error('Choose one flat HLS bundle with master.m3u8 and unique filenames.');
  const bytes=files.reduce((n,f)=>n+f.size,0);if(bytes>8e9||files.length>20000||files.some(f=>!f.size||f.size>16777216))throw new Error('Bundle exceeds the storage, file-count or 16 MiB segment limit.');
  $('r2ProgressLabel').textContent='Connecting to private storage…';
  try{reservation=await apiRequest(`/api/admin/r2/${title}/reservation`);$('r2Status').textContent='Resuming the existing storage reservation…';}catch(error){if(error.message!=='No resumable reservation')throw error;reservation=await apiRequest(`/api/admin/r2/${title}/reserve`,{method:'POST',body:JSON.stringify({bytes,files:files.length})});}

  const base=new URL(reservation.uploadBase);if(base.protocol!=='https:'||base.username||base.password)throw new Error('Invalid private media gateway');controller=new AbortController();let sent=0;
  const started=Date.now();let completedBytes=0;
  for(const file of files){if(closed)return;
   $('r2ProgressLabel').textContent=`Uploading file ${sent+1} of ${files.length}`;
   await new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('PUT',base.href+'/'+file.name);xhr.timeout=120000;
    const abort=()=>xhr.abort();controller.signal.addEventListener('abort',abort,{once:true});
    const clean=()=>controller.signal.removeEventListener('abort',abort);
    xhr.upload.onprogress=e=>{const done=completedBytes+e.loaded,percent=Math.min(100,done/bytes*100),speed=done/Math.max(1,(Date.now()-started)/1000);$('r2Progress').value=percent;$('r2Transfer').textContent=`${percent.toFixed(1)}% · ${(done/1e6).toFixed(1)} / ${(bytes/1e6).toFixed(1)} MB · ${(speed/1e6).toFixed(2)} MB/s · ${file.name}`;};
    xhr.onload=()=>{clean();xhr.status>=200&&xhr.status<300?resolve():reject(new Error(`Storage rejected file ${sent+1} (HTTP ${xhr.status}). Keep this folder selected, click Upload again to resume.`));};
    xhr.onerror=()=>{clean();reject(new Error('Connection to storage failed. Keep this folder selected, click Upload again to resume.'));};
    xhr.ontimeout=()=>{clean();reject(new Error('Upload timed out after 2 minutes. Click Upload again to resume.'));};xhr.onabort=()=>{clean();reject(new Error('Upload stopped.'));};xhr.send(file);
   });completedBytes+=file.size;sent++;$('r2Status').textContent=`Uploaded ${sent} of ${files.length} files.`;
  }
  if(!closed){transferred=true;const thumbnail=[...$('r2Files').files].find(f=>f.name==='thumbnail.jpg');if(thumbnail&&thumbnail.size<=250000){try{const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(thumbnail);});await apiRequest(`/api/admin/titles/${title}/artwork`,{method:'POST',body:JSON.stringify({jpeg:data})});}catch{toast('Video uploaded. Thumbnail could not be saved; you can add one during review.');}}root.dispatchEvent(new CustomEvent('studio:upload-state',{detail:{state:'complete'}}));$('r2Progress').value=100;$('r2ProgressLabel').textContent='Upload complete';$('r2Transfer').textContent=`${files.length} files · ${(bytes/1e6).toFixed(1)} MB transferred.`;$('r2Status').textContent='Next: review rights and captions below, then click Publish R2 video.';$('r2Publish').disabled=false;}

 }catch(e){if(!closed){$('r2ProgressLabel').textContent='Upload could not finish';$('r2Transfer').textContent=e.message;$('r2Status').textContent=e.message;}}finally{button.disabled=false;root.dispatchEvent(new CustomEvent('studio:upload-state',{detail:{state:transferred?'complete':'stopped'}}));}};
 $('r2Publish').onclick=async()=>{try{if(selectedTitle()!==title)throw new Error('Select the draft used for this upload before publishing.');const plan=release();if(!$('r2Rights').checked||!$('r2Captions').checked)throw new Error('Complete both publishing reviews.');await apiRequest(`/api/admin/r2/${title}/publish`,{method:'POST',body:JSON.stringify({bundleId:reservation.bundleId,rightsReviewed:true,captionsReviewed:true,...plan})});transferred=false;root.dispatchEvent(new CustomEvent('studio:upload-state',{detail:{state:'published'}}));$('r2Status').textContent=plan.releaseAt?'Scheduled for '+new Date(plan.releaseAt).toLocaleString()+'. It stays private until release.':'Published. Signed-in members can stream the real video.';toast(plan.releaseAt?'R2 release scheduled':'R2 video published');$('r2Publish').disabled=true;await onPublished?.();}catch(e){$('r2Status').textContent=e.message;}};
}
